#include <iostream>
#include <algorithm>
#include <cassert>
using U = unsigned long long;
const U LIMIT = 1000000;
struct Result { bool ok; U value; };
// x와y는 한도 이하입니다. 합을 만들기 전에 남은 여유를 검사합니다.
Result addChecked(U x, U y) {
    if (y > LIMIT-x) return {false,0};
    return {true,x+y};
}
Result halfMultiply(U small, U large) {
    if (small == 0) return {true,0};
    Result half = halfMultiply(small/2, large);
    if (!half.ok) return half;
    Result doubled = addChecked(half.value, half.value);
    if (!doubled.ok) return doubled;
    if (small%2 != 0) return addChecked(doubled.value, large);
    return doubled;
}
Result solve(U a, U b) {
    if(a>b) std::swap(a,b);
    return halfMultiply(a,b);
}
int main() {
    long long a,b;
    // 공백으로 구분한 정수 두 개입니다. 부호와 범위를 먼저 검사합니다.
    if(!(std::cin>>a>>b)||a<0||b<0||a>1000000||b>1000000) return 1;
    Result r=solve(static_cast<U>(a),static_cast<U>(b));
    if(r.ok) std::cout<<r.value<<'\n';
    else std::cout<<"OVERFLOW\n";
}
